#!/usr/bin/env bash
set -Eeuo pipefail

SID="${1:-25}"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/oldz-delux-v4-${SID}-${STAMP}"
TMP="$(mktemp -d /tmp/oldz-delux-v4.XXXXXX)"
trap 'rm -rf "$TMP"' EXIT

log(){ echo "[$1] ${*:2}"; }
fail(){ echo "[ERROR] $*" >&2; exit 1; }

[[ "$EUID" -eq 0 ]] || fail "Run as root"

CFG="/var/lib/hyper-cs16/servers/${SID}.json"
LEGACY_CFG="/etc/hyper-cs16/servers/${SID}.json"

json_get(){
  python3 - "$1" "$2" <<'PY'
import json,sys
try:
    d=json.load(open(sys.argv[1],encoding='utf-8'))
    print(d.get(sys.argv[2],"") or "")
except Exception:
    print("")
PY
}

ROOT=""
[[ -f "$CFG" ]] && ROOT="$(json_get "$CFG" path)"
[[ -z "$ROOT" && -f "$LEGACY_CFG" ]] && ROOT="$(json_get "$LEGACY_CFG" path)"
[[ -n "$ROOT" ]] || ROOT="/srv/hyper-cs16/servers/${SID}"
CSTRIKE="$ROOT/cstrike"
AMXX="$CSTRIKE/addons/amxmodx"
S="$AMXX/scripting"
P="$AMXX/plugins"
C="$AMXX/configs"
COMPILER="$S/amxxpc"
UNIT="hyper-cs16@${SID}.service"

[[ -d "$CSTRIKE" ]] || fail "cstrike not found: $CSTRIKE"
[[ -x "$COMPILER" ]] || fail "AMXX compiler not found/executable: $COMPILER"

mkdir -p "$BACKUP" "$P" "$S" "$C"

echo "================================================================"
echo " OLD ZOMBIE DELUX COMPLETE v4"
echo " Server: #$SID"
echo " Root:   $ROOT"
echo " Backup: $BACKUP"
echo "================================================================"

# ---------- unpack embedded payload ----------
cat > "$TMP/payload.b64" <<'PAYLOAD'

PAYLOAD
base64 -d "$TMP/payload.b64" > "$TMP/payload.tar.gz"
mkdir -p "$TMP/payload"
tar -xzf "$TMP/payload.tar.gz" -C "$TMP/payload"

# ---------- backup ----------
log 1 "Backing up current server files..."
for f in \
  "$S/zmpl.sma" "$P/zmpl.amxx" \
  "$S/zm_addon_knife.sma" "$P/zm_addon_knife.amxx" \
  "$S/oldz_zclass_desperado_delux.sma" "$P/oldz_zclass_desperado_delux.amxx" \
  "$S/oldz_delux_menu.sma" "$P/oldz_delux_menu.amxx" \
  "$S/oldz_delux_hook.sma" "$P/oldz_delux_hook.amxx" \
  "$C/plugins.ini"
do
  if [[ -f "$f" ]]; then
    mkdir -p "$BACKUP/$(dirname "${f#$CSTRIKE/}")"
    cp -a "$f" "$BACKUP/${f#$CSTRIKE/}"
  fi
done

# Keep a copy of current store-model source if present; we only patch it in-place later.
if [[ -f "$S/oldz_store_models.sma" ]]; then
  mkdir -p "$BACKUP/addons/amxmodx/scripting"
  cp -a "$S/oldz_store_models.sma" "$BACKUP/addons/amxmodx/scripting/oldz_store_models.sma"
fi
if [[ -f "$P/oldz_store_models.amxx" ]]; then
  mkdir -p "$BACKUP/addons/amxmodx/plugins"
  cp -a "$P/oldz_store_models.amxx" "$BACKUP/addons/amxmodx/plugins/oldz_store_models.amxx"
fi

# ---------- install clean sources/resources ----------
log 2 "Installing clean DELUX sources and resources..."
cp -a "$TMP/payload/addons/amxmodx/scripting/zmpl.sma" "$S/zmpl.sma"
cp -a "$TMP/payload/addons/amxmodx/scripting/zm_addon_knife.sma" "$S/zm_addon_knife.sma"
cp -a "$TMP/payload/addons/amxmodx/scripting/oldz_zclass_desperado_delux.sma" "$S/oldz_zclass_desperado_delux.sma"
cp -a "$TMP/payload/addons/amxmodx/scripting/oldz_delux_menu.sma" "$S/oldz_delux_menu.sma"
cp -a "$TMP/payload/addons/amxmodx/scripting/oldz_delux_hook.sma" "$S/oldz_delux_hook.sma"

for d in models sound sprites; do
  if [[ -d "$TMP/payload/$d" ]]; then
    cp -a "$TMP/payload/$d/." "$CSTRIKE/$d/"
  fi
done

# ---------- patch CURRENT oldz_store_models source without replacing the user's other fixes ----------
log 3 "Adding DELUX Reega fallback to current store-model plugin (without overwriting other fixes)..."
if [[ -f "$S/oldz_store_models.sma" ]]; then
python3 - "$S/oldz_store_models.sma" <<'PY'
from pathlib import Path
import sys
p=Path(sys.argv[1])
s=p.read_text(encoding='utf-8',errors='ignore')
orig=s
if 'DELUX_MODEL_PATH' not in s:
    s=s.replace('#define DELTA_MODEL_PATH "models/oldz_custom/Delta/Delta.mdl"',
                '#define DELTA_MODEL_PATH "models/oldz_custom/Delta/Delta.mdl"\n#define DELUX_MODEL_PATH "models/player/reega_imperator/reega_imperator.mdl"',1)
if 'precache_model(DELUX_MODEL_PATH)' not in s:
    s=s.replace('load_store_model_precache_list()','load_store_model_precache_list()\n\tif (file_exists(DELUX_MODEL_PATH)) precache_model(DELUX_MODEL_PATH)',1)
if 'stock bool:oldz_has_delux' not in s:
    marker='stock query_models(id)'
    helper='''stock bool:oldz_has_delux(id)\n{\n\tif (!is_user_connected(id)) return false\n\tnew flags = get_user_flags(id)\n\tnew dflag = read_flags("v")\n\treturn ((flags & ADMIN_LEVEL_H) && (flags & dflag)) ? true : false\n}\n\nstock apply_delux_fallback(id)\n{\n\tif (!oldz_has_delux(id) || !file_exists(DELUX_MODEL_PATH)) return\n\tcopy(g_active_model_path[id], charsmax(g_active_model_path[]), DELUX_MODEL_PATH)\n\toldz_set_store_human_model(id, DELUX_MODEL_PATH)\n\tschedule_apply(id)\n\tstart_model_enforce(id)\n}\n\n'''
    if marker in s:
        s=s.replace(marker,helper+marker,1)
# Only add fallback at the final equipped-model decision when the expected block exists.
if 'apply_delux_fallback(id)' in s and 'else\n\t{\n\t\tapply_delux_fallback(id)' not in s:
    block='''\tif (g_model_enabled[id])\n\t{\n\t\tschedule_apply(id)\n\t\tstart_model_enforce(id)\n\t}\n}'''
    repl='''\tif (g_model_enabled[id])\n\t{\n\t\tschedule_apply(id)\n\t\tstart_model_enforce(id)\n\t}\n\telse\n\t{\n\t\tapply_delux_fallback(id)\n\t}\n}'''
    if block in s:
        s=s.replace(block,repl,1)
if s != orig:
    compile(s,str(p),'exec') if False else None
    p.write_text(s,encoding='utf-8')
    print('[OK] oldz_store_models.sma patched')
else:
    print('[INFO] store-model DELUX fallback already present or source layout differs; no destructive rewrite performed')
PY
else
  log INFO "oldz_store_models.sma not found; DELUX player model fallback skipped."
fi

# ---------- compile ----------
log 4 "Compiling clean plugins..."
# The old Pawn compiler can crash on very large sources with an 8 MB shell stack.
ulimit -s unlimited 2>/dev/null || true

compile_one(){
  local src="$1" out="$2"
  local tmpout="$TMP/$out"
  echo "[AMXX] $src -> $out"
  rm -f "$tmpout"
  set +e
  ( cd "$S" && "$COMPILER" "$src" "-o$tmpout" ) >"$TMP/${src}.log" 2>&1
  local rc=$?
  set -e
  if [[ $rc -ne 0 || ! -s "$tmpout" ]]; then
    echo "[COMPILE FAILED] $src (rc=$rc)"
    tail -n 80 "$TMP/${src}.log" || true
    return 1
  fi
  cp -a "$tmpout" "$P/$out"
  chmod 0644 "$P/$out"
  chown cs16:www-data "$P/$out" 2>/dev/null || true
  echo "[OK] $out"
}

# Compile to temp first. Do not restart with half-built core.
compile_one "zmpl.sma" "zmpl.amxx" || fail "Clean zmpl.sma still failed to compile. Backup kept at $BACKUP"
compile_one "zm_addon_knife.sma" "zm_addon_knife.amxx" || fail "Knife plugin failed to compile"
compile_one "oldz_zclass_desperado_delux.sma" "oldz_zclass_desperado_delux.amxx" || fail "Desperado plugin failed to compile"
compile_one "oldz_delux_menu.sma" "oldz_delux_menu.amxx" || fail "DELUX menu failed to compile"
compile_one "oldz_delux_hook.sma" "oldz_delux_hook.amxx" || fail "DELUX hook failed to compile"

if [[ -f "$S/oldz_store_models.sma" ]]; then
  if ! compile_one "oldz_store_models.sma" "oldz_store_models.amxx"; then
    log WARN "Store models compile failed. Restoring its previous binary/source; the rest of DELUX stays installed."
    [[ -f "$BACKUP/addons/amxmodx/scripting/oldz_store_models.sma" ]] && cp -a "$BACKUP/addons/amxmodx/scripting/oldz_store_models.sma" "$S/oldz_store_models.sma"
    [[ -f "$BACKUP/addons/amxmodx/plugins/oldz_store_models.amxx" ]] && cp -a "$BACKUP/addons/amxmodx/plugins/oldz_store_models.amxx" "$P/oldz_store_models.amxx"
  fi
fi

# ---------- normalize plugins.ini ----------
log 5 "Normalizing plugins.ini..."
PLUGINS="$C/plugins.ini"
[[ -f "$PLUGINS" ]] || touch "$PLUGINS"
python3 - "$PLUGINS" <<'PY'
from pathlib import Path
import sys
p=Path(sys.argv[1])
lines=p.read_text(encoding='utf-8',errors='ignore').splitlines()
want=[
 'zmpl.amxx',
 'zm_addon_knife.amxx',
 'oldz_zclass_desperado_delux.amxx',
 'oldz_delux_menu.amxx',
 'oldz_delux_hook.amxx',
]
# Resource-heavy DELUX weapon providers stay disabled until precache budget is audited.
heavy={'oldz_delux_starchaser.amxx','oldz_delux_bloodmoon.amxx','oldz_delux_balrog95.amxx'}
out=[]; seen=set()
for line in lines:
    raw=line.strip()
    token=raw.lstrip(';').strip().split(None,1)[0].lower() if raw else ''
    if token in heavy:
        if token not in seen:
            out.append('; '+token+' ; disabled by DELUX v4: protects GoldSrc 512 precache limit')
            seen.add(token)
        continue
    if token in {x.lower() for x in want}:
        if token not in seen:
            out.append(token)
            seen.add(token)
        continue
    # old/duplicate Desperado builds must not coexist
    if token in {'zp_zclass_desperado.amxx','05_zp_zclass_desperado.amxx'}:
        out.append('; '+raw.lstrip(';').strip()+' ; replaced by oldz_zclass_desperado_delux.amxx')
        continue
    out.append(line)

# Insert missing plugins right after zmpl when possible.
insert_at=next((i+1 for i,x in enumerate(out) if x.strip().lower()=='zmpl.amxx'),len(out))
for plugin in want[1:]:
    if plugin.lower() not in seen:
        out.insert(insert_at,plugin)
        insert_at+=1
        seen.add(plugin.lower())
# Ensure zmpl itself exists if plugins.ini somehow lacked it.
if 'zmpl.amxx' not in seen:
    out.insert(0,'zmpl.amxx')

p.write_text('\n'.join(out).rstrip()+'\n',encoding='utf-8')
PY

# ---------- sync only added resources to current FastDL ----------
log 6 "Syncing DELUX resources to FastDL..."
FASTDL="/srv/hyper-cs16/fastdl/${SID}"
mkdir -p "$FASTDL"
for d in models sound sprites; do
  if [[ -d "$TMP/payload/$d" ]]; then
    mkdir -p "$FASTDL/$d"
    rsync -a "$TMP/payload/$d/" "$FASTDL/$d/"
  fi
done
find "$FASTDL" -type d -exec chmod 0755 {} + 2>/dev/null || true
find "$FASTDL" -type f -exec chmod 0644 {} + 2>/dev/null || true

# ---------- restart + rollback on boot failure ----------
log 7 "Restarting $UNIT..."
systemctl reset-failed "$UNIT" >/dev/null 2>&1 || true
set +e
systemctl restart "$UNIT"
sleep 10
systemctl is-active --quiet "$UNIT"
RUNNING=$?
set -e

if [[ $RUNNING -ne 0 ]]; then
  echo "[ERROR] Server did not stay online. Restoring previous core/plugin binaries and plugins.ini..."
  for rel in \
    addons/amxmodx/scripting/zmpl.sma addons/amxmodx/plugins/zmpl.amxx \
    addons/amxmodx/scripting/zm_addon_knife.sma addons/amxmodx/plugins/zm_addon_knife.amxx \
    addons/amxmodx/scripting/oldz_zclass_desperado_delux.sma addons/amxmodx/plugins/oldz_zclass_desperado_delux.amxx \
    addons/amxmodx/scripting/oldz_delux_menu.sma addons/amxmodx/plugins/oldz_delux_menu.amxx \
    addons/amxmodx/scripting/oldz_delux_hook.sma addons/amxmodx/plugins/oldz_delux_hook.amxx \
    addons/amxmodx/configs/plugins.ini
  do
    [[ -f "$BACKUP/$rel" ]] && cp -a "$BACKUP/$rel" "$CSTRIKE/$rel"
  done
  systemctl restart "$UNIT" || true
  echo "Last journal before rollback:"
  journalctl -u "$UNIT" -n 100 --no-pager -o cat || true
  fail "DELUX v4 rolled back because the server failed to boot. Backup: $BACKUP"
fi

# Look specifically for fresh fatal/plugin errors.
RECENT="$(journalctl -u "$UNIT" --since '-20 seconds' --no-pager -o cat 2>/dev/null || true)"
if echo "$RECENT" | grep -Eq 'FATAL ERROR|PF_precache_.*512|Run time error 19.*(oldz_delux|desperado|zm_addon_knife)'; then
  echo "$RECENT" | tail -n 120
  fail "Server is active but fresh DELUX/precache errors were detected. Backup: $BACKUP"
fi

# ---------- final checks ----------
log 8 "Final verification..."
grep -Eq '^[[:space:]]*oldz_zclass_desperado_delux\.amxx' "$PLUGINS" || fail "Desperado is not active in plugins.ini"
grep -Eq '^[[:space:]]*oldz_delux_menu\.amxx' "$PLUGINS" || fail "DELUX menu is not active"
grep -Eq '^[[:space:]]*oldz_delux_hook\.amxx' "$PLUGINS" || fail "DELUX hook is not active"
grep -Eq '^[[:space:]]*zm_addon_knife\.amxx' "$PLUGINS" || fail "Knife plugin is not active"

echo
echo "================================================================"
echo " [SUCCESS] OLD ZOMBIE DELUX v4 installed"
echo "================================================================"
echo "DELUX access: t + v"
echo ""
echo "Now integrated in:"
echo "  - Main menu status: DELUX / ADMIN + DELUX"
echo "  - Privileges: VIP / DELUX / ADMIN"
echo "  - Zombie classes: Desperado [DELUX] (DELUX + ADMIN)"
echo "  - Knives: Wolf Axe [DELUX] under Fire Hammer"
echo "  - /delux: weapons / Desperado / knife / hook / bonuses"
echo "  - bind q +dhook: 20 uses per round"
echo ""
echo "Heavy DELUX weapon providers remain disabled on purpose because the"
echo "previous build exceeded GoldSrc's 512 precache limit. The DELUX menu"
echo "handles their absence safely instead of crashing the server."
echo ""
echo "Backup: $BACKUP"
